(* Fault latching — any safety event sets fault *)
IF NOT Emergency_Stop OR Abort_PB OR Overload THEN
    Fault_Latched := TRUE;
END_IF;

(* Two-condition reset: safe state AND operator action *)
IF Reset_PB
   AND Emergency_Stop      (* E-Stop healthy *)
   AND NOT Abort_PB        (* Abort cleared *)
   AND NOT Overload        (* Overload cleared *)
   AND Fault_Latched THEN  (* Only resets if actually faulted *)
    Fault_Latched := FALSE;
    Step_State := 0;       (* Return to safe idle *)
END_IF;
